const grid=document.querySelector('#project-grid');
const asset=(name)=>'assets/'+name;
grid.innerHTML=projects.map((p,i)=>'<article class="project-card" data-categories="'+p.category.join(' ')+'"><button class="project-image-button '+(p.imageClass||'')+'" data-project="'+p.id+'" aria-label="Open '+p.title+'"><img class="project-image" src="'+asset(p.image)+'" alt="'+p.title+' — original project evidence" loading="lazy"><span class="project-open" aria-hidden="true">↗</span></button><div class="project-meta"><span>'+String(i+1).padStart(2,'0')+' / '+p.kicker+'</span><span>'+p.year+'</span></div><h3><button class="project-title-button" data-project="'+p.id+'">'+p.title+'</button></h3><p>'+p.summary+'</p></article>').join('');
function filterProjects(filter){
document.querySelectorAll('[data-filter]').forEach(b=>{const on=b.dataset.filter===filter;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});
let n=0;document.querySelectorAll('.project-card').forEach((card,i)=>{const show=filter==='all'||projects[i].category.includes(filter);card.hidden=!show;if(show)n++;});
document.querySelector('#filter-status').textContent=n+' projects shown.';
}
const projectDialog=document.querySelector('#project-dialog'),explorerDialog=document.querySelector('#explorer-dialog');
function syncDialog(){document.body.classList.toggle('dialog-open',projectDialog.open||explorerDialog.open);}
function openProject(id){
const p=projects.find(x=>x.id===id);if(!p)return;
if(explorerDialog.open)explorerDialog.close();
document.querySelector('#project-kicker').textContent=p.kicker;
document.querySelector('#project-body').innerHTML='<div class="project-detail-heading"><h2 id="project-title">'+p.title+'</h2><div class="detail-tags">'+p.tags.map(t=>'<span>'+t+'</span>').join('')+'</div></div><img class="detail-main" src="'+asset(p.image)+'" alt="'+p.title+'"><div class="project-detail-text"><div><h3>PROJECT SCOPE</h3><p>'+p.scope+'</p></div><div><h3>MY CONTRIBUTION</h3><ul>'+p.contribution.map(c=>'<li>'+c+'</li>').join('')+'</ul></div></div><div class="detail-evidence"><h3>THE EVIDENCE</h3><div class="evidence-grid">'+p.evidence.map(e=>'<figure><a href="'+asset(e[0])+'" target="_blank" rel="noopener" aria-label="Open full-size evidence image"><img src="'+asset(e[0])+'" alt="'+e[1]+'" loading="lazy"></a><figcaption>'+e[1]+' · Click to enlarge ↗</figcaption></figure>').join('')+'</div></div><div class="project-detail-footer"><p>'+p.note+'</p><a class="text-link" href="'+asset(p.download)+'" download>Download evidence <span>↓</span></a></div>';
projectDialog.showModal();projectDialog.scrollTop=0;syncDialog();
}
let model,modelPromise,currentSystem='all';
const systems={
all:{name:'All systems',eyebrow:'CONNECTED SERVICES',title:'A look beneath the surface.',description:'Isolate a discipline to see its route through the building, then explore the related work.',project:'power'},
electrical:{name:'Electrical',eyebrow:'E / ELECTRICAL',title:'A route for every connection.',description:'Copper-coloured containment, distribution boards and lighting illustrate electrical routes through the building.',project:'power'},
mechanical:{name:'Mechanical',eyebrow:'M / MECHANICAL',title:'Space for the services.',description:'Ducts and terminal locations show the space that mechanical services share with electrical containment.',project:'warehouse'},
plumbing:{name:'Plumbing',eyebrow:'P / PLUMBING',title:'Connections across levels.',description:'Teal pipework illustrates horizontal distribution and vertical risers alongside the other services.',project:'warehouse'},
fire:{name:'Fire protection',eyebrow:'F / FIRE PROTECTION',title:'Protection within the model.',description:'Red pipework illustrates sprinkler distribution. My actual fire-related work includes a hose reel cabinet family and electrical fire alarm modelling.',project:'warehouse'}
};
function setSystem(key){currentSystem=systems[key]?key:'all';const s=systems[currentSystem];document.querySelectorAll('[data-system]').forEach(b=>{const on=b.dataset.system===currentSystem;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});document.querySelector('#model-mode').textContent=s.name;document.querySelector('#system-eyebrow').textContent=s.eyebrow;document.querySelector('#system-title').textContent=s.title;document.querySelector('#system-description').textContent=s.description;model?.setSystem(currentSystem);}
async function openExplorer(system='all'){
if(projectDialog.open)projectDialog.close();
if(!explorerDialog.open)explorerDialog.showModal();syncDialog();setSystem(system);
try{
if(!modelPromise){modelPromise=import('./model.js').then(m=>m.createModel(document.querySelector('#model-canvas'),key=>setSystem(key))).then(m=>{model=m;document.querySelector('#model-loading').hidden=true;return m;});}
await modelPromise;requestAnimationFrame(()=>{model.resize();model.setSystem(currentSystem);model.setExplode(+document.querySelector('#explode').value/100);model.resume();});
}catch(error){document.querySelector('#model-loading').hidden=false;document.querySelector('#model-loading').textContent='The 3D view could not start on this device. You can still explore all project evidence in the gallery.';console.error('3D explorer unavailable:',error);}
}
document.addEventListener('click',e=>{
const filter=e.target.closest('[data-filter]');if(filter)filterProjects(filter.dataset.filter);
const ribbon=e.target.closest('[data-ribbon-filter]');if(ribbon)filterProjects(ribbon.dataset.ribbonFilter);
const project=e.target.closest('[data-project]');if(project)openProject(project.dataset.project);
const highlight=e.target.closest('[data-highlight]');if(highlight)openExplorer(highlight.dataset.highlight);
if(e.target.closest('[data-open-explorer]'))openExplorer();
const system=e.target.closest('[data-system]');if(system)setSystem(system.dataset.system);
if(e.target.closest('[data-close-project]'))projectDialog.close();
if(e.target.closest('[data-close-explorer]'))explorerDialog.close();
});
document.querySelector('#related-project').addEventListener('click',()=>openProject(systems[currentSystem].project));
document.querySelector('#explode').addEventListener('input',e=>{document.querySelector('#explode-value').value=e.target.value+'%';model?.setExplode(+e.target.value/100);});
document.querySelector('#reset-view').addEventListener('click',()=>{document.querySelector('#explode').value=35;document.querySelector('#explode-value').value='35%';model?.reset();setSystem('all');});
for(const d of [projectDialog,explorerDialog]){d.addEventListener('close',()=>{syncDialog();if(d===explorerDialog)model?.pause();});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});}
const menu=document.querySelector('.menu-button'),mobileNav=document.querySelector('#mobile-nav');
menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));menu.setAttribute('aria-label',expanded?'Open navigation':'Close navigation');mobileNav.hidden=expanded;});
mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobileNav.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}));
document.querySelector('#year').textContent=String(new Date().getFullYear());
filterProjects('all');
